    by rw [h_identity_on_1, neg_one_eq_neg_one]
  -- Show that f is the identity on integers
  have h_identity_on_int : ∀ n : ℤ, f n = n :=
    by intro n; induction n using Int.induction with d hd; simp [hd, h_identity_on_1, h_identity_on_neg_one]
